const r8Json=x=>JSON.parse(JSON.stringify(x));
function r8Fixture(target,debt='short',day='2026-09-03') {
 const s=state(),offset=n=>{const [y,m,d]=day.split('-').map(Number);return new Date(Date.UTC(y,m-1,d+n)).toISOString().slice(0,10);};
 if(target===undefined)delete s.sleep.cleanH;else s.sleep.cleanH=target;
 s.sleep.nights=[-3,-2,-1,0].map(n=>({d:offset(n),h:debt==='short'?(n===-1?2:8):debt==='three-night'?6.6:8}));
 s.reads=[{d:day,w:180,pt:180}];s.dailyLogs=Object.fromEntries([-3,-2,-1,0].map(n=>[offset(n),{cal:2200,pro:180,steps:10000}]));s.sessionLog={[day]:{entries:[]}};return {s,offset};
}
function r8Read(s,day='2026-09-03',control=false) {
 const before=structuredClone(s),trace=[],base=clockAt(day),clock={...base};
 for(const k of Object.keys(base))if(typeof base[k]==='function')clock[k]=(...a)=>{trace.push(k);return base[k](...a);};
 const T=createEngine({clock,ids:{fresh:()=>{assert.fail('Today must not allocate an ID');}}}).__test;
 let rate,energy,focus,levers,rec;
 if(control){rate=T.currentRate(s);energy=T.energyBalanceTarget(s);focus=T.nowFocus(s);levers=T.fiveLevers(s);rec=T.recoveryIndex(s);}
 else {rec=T.recoveryIndex(s);focus=T.nowFocus(s);levers=T.fiveLevers(s);}
 const fix=T.theOneFix(s),order=T.marchingOrder(s),now=T.nowModel(s);
 assert.deepEqual(s,before,'All three actual Today consumers preserve every recorded field');
 return {T,rec,focus,levers,fix,order,now,trace:[...trace],rate,energy};
}
function r8NoClearance({fix,order,now}) {
 assert.doesNotMatch(JSON.stringify({fix,order,move:now.move}),/Nothing to fix|five are covered|no lever worth pulling|sleep are all covered|NOTHING NEEDS YOU/,'R8-TODAY-FALSE-CLEARANCE');
}
function r8ActualWarnings({T,rec,fix,order,now}) {
 assert.ok(rec.flags.length,'Must reach actual recorded warnings');
 for(const f of rec.flags)for(const [consumer,text,plain]of [['fix',fix.body,false],['order',order.why,false],['move',now.move.body,true]]) {
  assert.ok(text.includes(plain?T._plain9(f.receipt):f.receipt),consumer+' retains actual '+f.k+' receipt');
  assert.ok(text.includes(plain?T._plain9(f.fix):f.fix),consumer+' retains actual '+f.k+' action');
 }
}
for(const [name,target]of r8Targets)for(const debt of ['short','three-night'])test(`FG5 R8 exact reviewer ${name} ${debt}`,()=>{
 const {s}=r8Fixture(target,debt),out=r8Read(s),{T,rec,focus,levers,fix,order,now,trace}=out,sleep=rec.flags.find(f=>f.k==='sleep');
 assert.equal(focus.owed.length,0,'All three previous calendar nights and current logging close the decision prerequisites');assert.ok(sleep);assert.ok(T.currentSleepObservation(s));
 if(Number.isFinite(target)) {
  assert.equal(sleep.cost,target===8&&debt==='short'?20:30);assert.equal(fix.rung,'sleep');assert.equal(now.move.kind,'fix');assert.equal(now.move.lever,'SLEEP');assert.equal(order.why,fix.title);
  const ref=R8_FINITE_S.find(r=>r.target===target&&r.debt===debt);assert.deepEqual(r8Json({fix,order,now}),ref.outputs,'Complete finite-target Today outputs stay exactly S');assert.deepEqual(trace,r9Trace(ref.trace),'Finite-target trace removes only the redundant workout date query');return;
 }
 assert.equal(sleep.cost,null);assert.equal(rec.score,null);assert.equal(rec.lever,null);assert.equal(rec.band,'UNKNOWN');assert.equal(levers.sleep.state,'quiet');
 assert.equal(fix.state,'quiet');assert.equal(fix.lever,null);assert.equal(fix.title,'Recorded recovery warnings');assert.equal(now.move.kind,'quiet');r8NoClearance(out);r8ActualWarnings(out);
 for(const text of [fix.body,order.why,now.move.body])assert.match(text,/Recovery rating unavailable\./);
});
